// Get system user ID from n8n environment
const systemUserId = process.env.LOANOS_SYSTEM_USER_ID;
if (!systemUserId) {
  throw new Error('LOANOS_SYSTEM_USER_ID not set in n8n environment variables. Set it to Adams auth.users UUID.');
}

// Arive webhooks nest payload under body
const body = $json.body || $json;

// Normalize: return null for empty/missing fields
const n = (val) => {
  if (val === null || val === undefined || val === '') return null;
  return val;
};

const rawEmail = n(body.loanBorrower1_emailAddressText);
if (!rawEmail) {
  throw new Error('Missing required field: loanBorrower1_emailAddressText');
}

const ariveLoanId = String(body.ariveLoanId ?? '');
if (!ariveLoanId) {
  throw new Error('Missing required field: ariveLoanId');
}

return [{
  json: {
    // Contact fields
    email: rawEmail.toLowerCase().trim(),
    firstName: n(body.loanBorrower1_firstName) || '',
    lastName: n(body.loanBorrower1_lastName) || '',
    phone: n(body.loanBorrower1_mobilePhoneText),
    mailingStreet: n(body.loanProperty_streetAddressText),
    mailingCity: n(body.loanProperty_cityText),
    mailingState: n(body.loanProperty_stateText),
    mailingZip: n(body.loanProperty_postalCodeText),
    // Loan fields
    ariveLoanId,
    status: n(body.currentLoanStatus_status),
    firstPaymentDate: n(body.keyDates_firstPaymentDate),
    estClosingDate: n(body.keyDates_closingContingencyDate),
    fundingDate: n(body.keyDates_estimatedFundingDate),
    salesContractDate: n(body.keyDates_salesContractDate),
    // System
    systemUserId,
    rawPayload: body
  }
}];

// Supabase upsert with return=representation returns an array
const response = $input.item.json;
const contact = Array.isArray(response) ? response[0] : response;

if (!contact || !contact.id) {
  throw new Error('Upsert Contact returned no record. Response: ' + JSON.stringify(response));
}

// Carry forward all fields needed for downstream nodes
const fields = $('Extract Org ID').item.json;
return [{
  json: {
    contactId: contact.id,
    ariveLoanId: fields.ariveLoanId,
    status: fields.status,
    firstPaymentDate: fields.firstPaymentDate,
    estClosingDate: fields.estClosingDate,
    fundingDate: fields.fundingDate,
    salesContractDate: fields.salesContractDate,
    systemUserId: fields.systemUserId,
    orgId: fields.orgId,
    rawPayload: fields.rawPayload
  }
}];

const response = $input.item.json;
const loan = Array.isArray(response) ? response[0] : response;

if (!loan || !loan.id) {
  throw new Error('Upsert Loan returned no record. Response: ' + JSON.stringify(response));
}

const prev = $('Extract Contact ID').item.json;
return [{
  json: {
    loanId: loan.id,
    contactId: prev.contactId,
    ariveLoanId: prev.ariveLoanId,
    status: prev.status,
    systemUserId: prev.systemUserId,
    orgId: prev.orgId
  }
}];

