={{ JSON.stringify({
  action: 'loan_created',
  entity_type: 'loan',
  entity_id: $json.loanId,
  loan_id: $json.loanId,
  contact_id: $json.contactId,
  metadata: {
    arive_loan_id: $json.ariveLoanId,
    status: $json.status,
    source: 'arive_webhook'
  },
  user_id: $json.systemUserId,
  organization_id: $json.orgId || null
}) }}

={{ JSON.stringify({
  action: 'arive.webhook.error',
  entity_type: 'loan',
  entity_id: null,
  metadata: {
    error_message: $json.execution.error.message,
    node_name: $json.execution.error.node ? $json.execution.error.node.name : 'unknown',
    workflow_id: $json.workflow.id,
    execution_id: $json.execution.id,
    source: 'arive_new_loan_webhook'
  },
  user_id: process.env.LOANOS_SYSTEM_USER_ID
}) }}

