// profiles endpoint returns an array
const response = $input.item.json;
const profiles = Array.isArray(response) ? response : [response];
const orgId = profiles.length > 0 ? (profiles[0].organization_id || null) : null;

// Carry forward all fields from Extract Loan Fields
const fields = $('Extract Loan Fields').item.json;
return [{
  json: {
    ...fields,
    orgId
  }
}];
